import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.B65tnXzx.js";const g=JSON.parse('{"title":"总览","description":"","frontmatter":{"title":"总览","titleEn":"Overview","category":"guide","outline":"deep"},"headers":[],"relativePath":"zh/guide/index.md","filePath":"zh/guide/index.md"}'),r={name:"zh/guide/index.md"};function o(i,a,p,l,c,d){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="📖-总览" tabindex="-1">📖 总览 <a class="header-anchor" href="#📖-总览" aria-label="Permalink to &quot;📖 总览&quot;">​</a></h1><blockquote><p>本文档涵盖 <strong>libreforge</strong> 效果框架及其与 <strong>EcoEnchants</strong>（eco 生态驱动的附魔插件）的集成。</p></blockquote><h2 id="什么是-libreforge" tabindex="-1">什么是 libreforge？ <a class="header-anchor" href="#什么是-libreforge" aria-label="Permalink to &quot;什么是 libreforge？&quot;">​</a></h2><p><strong>libreforge</strong> 是所有 Auxilor &quot;eco&quot; 系列插件背后的效果引擎。它提供统一、数据驱动的效果系统：服主无需编写代码，只需通过 YAML 配置文件组合 <strong>Effects（效果）</strong>、<strong>Triggers（触发器）</strong>、<strong>Conditions（条件）</strong>、<strong>Filters（过滤器）</strong> 和 <strong>Mutators（变异器）</strong>，即可创建几乎任何游戏机制——伤害、治疗、粒子、经济、成长系统等。</p><p>该系统包含 <strong>200+ 效果、100+ 触发器、100+ 条件</strong>，全部无需编写一行 Java 代码即可配置。</p><h2 id="什么是-ecoenchants" tabindex="-1">什么是 EcoEnchants？ <a class="header-anchor" href="#什么是-ecoenchants" aria-label="Permalink to &quot;什么是 EcoEnchants？&quot;">​</a></h2><p><strong>EcoEnchants</strong> 是构建在 eco 与 libreforge 之上的自定义附魔插件。它允许你创建完全自定义的附魔——每个附魔都是一个独立的配置文件，使用 libreforge 效果系统定义其游戏行为。附魔等级可通过 <code>%level%</code> 占位符引用，实现效果参数的动态缩放。</p><h2 id="文档结构" tabindex="-1">文档结构 <a class="header-anchor" href="#文档结构" aria-label="Permalink to &quot;文档结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>说明</th></tr></thead><tbody><tr><td><a href="./effect-basics">指南</a></td><td>Effect 系统基础、YAML 结构、通用参数</td></tr><tr><td><a href="./../effects/">Effects 效果</a></td><td>所有可用效果的完整参数参考</td></tr><tr><td><a href="./../triggers/">Triggers 触发器</a></td><td>激活触发型效果的全部触发器</td></tr><tr><td><a href="./../conditions/">Conditions 条件</a></td><td>限制效果激活的全部条件</td></tr><tr><td><a href="./../mutators/">Mutators 变异器</a></td><td>转换效果数据的全部变异器</td></tr><tr><td><a href="./../examples/">示例</a></td><td>即用配置方案</td></tr></tbody></table><h2 id="生态架构总览" tabindex="-1">生态架构总览 <a class="header-anchor" href="#生态架构总览" aria-label="Permalink to &quot;生态架构总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eco（基础核心库）</span></span>
<span class="line"><span> ├── 数学表达式与占位符</span></span>
<span class="line"><span> ├── 价格系统</span></span>
<span class="line"><span> ├── 点数系统</span></span>
<span class="line"><span> └── 共享配置工具</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>libreforge（效果框架）</span></span>
<span class="line"><span> ├── Effects（动作）</span></span>
<span class="line"><span> ├── Triggers（事件）</span></span>
<span class="line"><span> ├── Conditions（要求）</span></span>
<span class="line"><span> ├── Filters（触发器收窄）</span></span>
<span class="line"><span> └── Mutators（数据转换）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>EcoEnchants（附魔插件）</span></span>
<span class="line"><span> └── 自定义附魔 = 使用效果系统的 YAML 配置</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">💡 提示</p><p>本文档基于官方 Auxilor Wiki（<a href="https://plugins.auxilor.io/" target="_blank" rel="noreferrer">plugins.auxilor.io</a>）。当来源信息存在歧义或不完整时，会使用 📝 编者注 标注说明。</p></div>`,12)])])}const f=s(r,[["render",o]]);export{g as __pageData,f as default};
